          "command": "jq -r '.tool_input.content // .tool_input.new_string // empty' | grep -qiE 'Co-Authored-By|\ud83e\udd16 Generated with' && printf '%s' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"deny\",\"permissionDecisionReason\":\"law_operations: no Co-Authored-By trailer, and no trailer naming a model or tool - including in a commit-message file. Write it without.\"}}' || true",
          "timeout": 10,
          "statusMessage": "checking for a forbidden trailer"
        }
      ]
