309	pub fn run_opi(p: u64, n: usize, trials: usize, seed: u64) -> Result<OpiResult, String> {
310	    if !is_prime(p) {
311	        return Err(format!("p={} is not prime -- GF(p) arithmetic needs a prime field", p));
312	    }
313	    let m = (p - 1) as usize;
314	    if n == 0 || n >= m {
315	        return Err(format!("n={} must satisfy 0 < n < p-1={}", n, m));
316	    }
317	    let r = (p / 2) as usize;
318	    let gamma = find_primitive_root(p);
319	
320	    let mut rng = Xorshift(seed ^ 0x9E3779B97F4A7C15);
321	
322	    // The m=p-1 constraint points: gamma^0 .. gamma^{p-2}, every
323	    // nonzero field element exactly once (gamma is primitive).
324	    let points: Vec<u64> = {
325	        let mut v = Vec::with_capacity(m);
326	        let mut cur = 1u64;
327	        for _ in 0..m {
328	            v.push(cur);
329	            cur = mul_mod(cur, gamma, p);
330	        }
331	        v
332	    };
333	
334	    // Independent random size-r subset of GF(p) for each constraint --
335	    // the "balanced" instance, size stated by eq. 15, membership drawn
336	    // fresh per constraint (the paper's own "assuming the f_i are
337	    // random" analysis assumption, not a weaker stand-in for it).
338	    let sat_sets: Vec<Vec<bool>> = (0..m)
339	        .map(|_| {
340	            let mut membership = alloc::vec![false; p as usize];
341	            let mut count = 0usize;
342	            while count < r {
343	                let v = rng.next_below(p) as usize;
344	                if !membership[v] {
345	                    membership[v] = true;
346	                    count += 1;
347	                }
348	            }
349	            membership
350	        })
351	        .collect();
352	
353	    #[cfg(feature = "hosted")]
354	    let t0 = now_micros();
355	
356	    let mut best_satisfied = 0usize;
357	    for _ in 0..trials {
358	        // Prange: keep a random n of the m constraints.
359	        let mut idx: Vec<usize> = (0..m).collect();
360	        for i in 0..n {
361	            let j = i + rng.next_below((m - i) as u64) as usize;
362	            idx.swap(i, j);
363	        }
364	        let kept = &idx[..n];
365	        // For each kept constraint, pick an element of its F_i.
366	        let subset: Vec<(u64, u64)> = kept
367	            .iter()
368	            .map(|&i| {
369	                let members: Vec<u64> = (0..p).filter(|&v| sat_sets[i][v as usize]).collect();
370	                let pick = members[rng.next_below(members.len() as u64) as usize];
371	                (points[i], pick)
372	            })
373	            .collect();
374	        let coeffs = lagrange_interpolate(&subset, p);
375	        let satisfied = (0..m)
376	            .filter(|&i| sat_sets[i][eval_poly(&coeffs, points[i], p) as usize])
377	            .count();
378	        if satisfied > best_satisfied {
379	            best_satisfied = satisfied;
380	        }
381	    }
382	
383	    #[cfg(feature = "hosted")]
384	    let micros = now_micros() - t0;
385	
386	    let n_f = n as f64;
387	    let m_f = m as f64;
388	    let p_f = p as f64;
389	    let r_f = r as f64;
390	    let phi_pr_theory = n_f / m_f + (1.0 - n_f / m_f) * (r_f / p_f);
391	    let half_over_p = n_f / (2.0 * p_f);
392	    let phi_dqi_asymptotic = 0.5 + sqrt_f64(half_over_p * (1.0 - half_over_p));
393	
394	    // The real DQI number: Lemma 9.2's exact finite-m formula, computed by
395	    // solving the actual (ell+1)x(ell+1) eigenvalue problem at this m, not
396	    // the m->p asymptotic limit above. ell = floor((n+1)/2), the Berlekamp-
397	    // Massey correction radius for this Reed-Solomon code (§5).
398	    let ell = (n + 1) / 2;
399	    let d_diag = (p_f - 2.0 * r_f) / sqrt_f64(r_f * (p_f - r_f));
400	    let lambda_max = semicircle_lambda_max(m, ell, d_diag);
401	    let phi_dqi_exact = r_f / p_f + sqrt_f64(r_f * (p_f - r_f)) / (m_f * p_f) * lambda_max;
402	
403	    Ok(OpiResult {
404	        p,
405	        n,
406	        m,
407	        r,
408	        gamma,
409	        trials,
410	        best_satisfied,
411	        best_fraction: best_satisfied as f64 / m as f64,
412	        phi_pr_theory,
413	        ell,
414	        lambda_max,
415	        phi_dqi_exact,
416	        phi_dqi_asymptotic,
417	        #[cfg(feature = "hosted")]
418	        micros,
419	    })
420	}
421	
422	pub fn report(res: &OpiResult) -> String {
423	    let mut out = String::new();
424	    out.push_str(&format!(
425	        "opi: p={}, n={}, m=p-1={}, r=floor(p/2)={}, gamma={} (n/p={:.4})\n",
426	        res.p, res.n, res.m, res.r, res.gamma, res.n as f64 / res.p as f64
427	    ));
428	    out.push_str("  balanced (Def. 2.2, eq. 15): each of the m constraints has an independent random size-r satisfying set\n");
429	    out.push_str(&format!(
430	        "  Prange's algorithm (§11.3), {} trials: best {} / {} satisfied (fraction {:.4})\n",
431	        res.trials, res.best_satisfied, res.m, res.best_fraction
