45	\begin{document}
46	\title{\textbf{The Averaged Representation Count of an Additive Basis}}
47	\author{C.\ Lando Mills\\
48	Trabuco Canyon, California\\
49	\texttt{c.landonmills@gmail.com}\\
50	ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
51	\date{11 August 2026}
52	\maketitle
53	
54	\begin{abstract}
55	For $A \subseteq \mathbb{N}$ let $r_A(n)$ count the ordered pairs from $A$
56	summing to $n$. The partial sum $\sum_{n<N} r_A(n)$ is not an approximation to
57	anything: it counts exactly the pairs from $A$ whose sum lies below $N$, and both
58	entries of such a pair are themselves below $N$. Hence the partial sum is at most
59	$|A \cap [0,N)|^2$.
60	
61	If $A$ is a basis of order two then the same partial sum is at least $N - N_0$,
62	because every large $n$ has a representation. The two bounds together give the
63	square-root density estimate $N - N_0 \le |A \cap [0,N)|^2$, and they squeeze the
64	average $N^{-1}\sum_{n<N} r_A(n)$ between a quantity tending to $1$ and
65	$|A \cap [0,N)|^2 / N$. A basis whose counting function is $O(\sqrt N)$
66	therefore has bounded average, so the average is the wrong statistic for
67	detecting the irregularity that the Erd\H{o}s--Fuchs theorem concerns.
68	\end{abstract}
69	
70	\section{The partial sum is a pair count}
71	
72	\begin{definition}
73	For $A \subseteq \mathbb{N}$ put
74	\[
75	  r_A(n) \;=\; \#\{ (a,b) \in A \times A \;:\; a + b = n \},
76	  \qquad
77	  \operatorname{avg}_A(N) \;=\; \frac1N \sum_{n<N} r_A(n).
78	\]
79	\end{definition}
80	
81	\begin{theorem}[Fibring]
82	\label{thm:count}
83	\[
84	  \boxed{\;
85	  \sum_{n<N} r_A(n)
86	   \;=\; \#\{ (a,b) \in A^2 \;:\; a < N,\ b < N,\ a + b < N \}. \;}
87	\]
88	\end{theorem}
89	
90	\begin{proof}
91	Fibre the right-hand set over the map $(a,b) \mapsto a+b$, which lands in
92	$\{0, \dots, N-1\}$ by the third condition. The fibre over $n$ consists of the
93	pairs with $a + b = n$ and both entries in $A$; the side conditions $a, b < N$ are
94	implied by $a + b = n < N$, so that fibre is counted by $r_A(n)$.
95	\end{proof}
96	
97	\begin{corollary}
98	\label{cor:upper}
99	$\displaystyle \sum_{n<N} r_A(n) \;\le\; |A \cap [0,N)|^2$.
100	\end{corollary}
101	
102	\begin{proof}
103	Every counted pair has both entries in $A \cap [0,N)$, so the set injects into the
104	square of that set.
105	\end{proof}
106	
107	\section{What a basis forces}
108	
109	\begin{definition}
110	$A$ is a \emph{basis of order two} when there is $N_0$ with $n \in A + A$ for
111	every $n \ge N_0$.
112	\end{definition}
113	
114	\begin{theorem}[Square-root density]
115	\label{thm:sqrt}
116	If $A$ is a basis of order two with threshold $N_0$, then for every $N \ge N_0$,
117	\[
118	  \boxed{\; N - N_0 \;\le\; |A \cap [0,N)|^2 . \;}
119	\]
120	\end{theorem}
121	
122	\begin{proof}
123	Each $n$ with $N_0 \le n < N$ has a representation, so $r_A(n) \ge 1$; summing
124	over those $N - N_0$ values gives $N - N_0 \le \sum_{n<N} r_A(n)$, and
125	\Cref{cor:upper} finishes.
126	\end{proof}
127	
128	So a basis of order two has at least $\sqrt{N - N_0}$ elements below $N$:
129	square-root density is necessary. \Cref{thm:sqrt} is the useful consequence of the
130	basis hypothesis, and it is a statement about the size of $A$, not about the size
131	of $r_A$.
132	
133	\section{The average is bounded}
134	
135	\begin{theorem}
136	\label{thm:avg}
137	If $|A \cap [0,N)| \le C \sqrt{N}$ then $\operatorname{avg}_A(N) \le C^2$.
138	\end{theorem}
139	
140	\begin{proof}
141	By \Cref{cor:upper}, $\sum_{n<N} r_A(n) \le |A \cap [0,N)|^2 \le C^2 N$; divide
142	by $N$.
143	\end{proof}
144	
145	\begin{corollary}
146	A basis of order two whose counting function is $O(\sqrt N)$ has bounded averaged
147	representation count. In particular the basis hypothesis alone implies neither
148	that $\operatorname{avg}_A(N) \to \infty$ nor any growth rate for it.
149	\end{corollary}
150	
151	The lower side is equally rigid: by \Cref{thm:sqrt},
152	$\operatorname{avg}_A(N) \ge 1 - N_0/N$, so for every basis the average is pinned
153	near $1$ from below. Between the two bounds there is no room for a growth
154	statement.
155	
156	\section{Where the Erd\H{o}s--Fuchs theorem lives}
157	
158	The Erd\H{o}s--Fuchs theorem concerns the error term rather than the average. It
159	asserts that
160	\[
161	  \sum_{n \le N} r_A(n)
162	   \;=\; cN \;+\; o\!\left( N^{1/4} (\log N)^{-1/2} \right)
163	\]
164	is impossible for $c > 0$: the partial sums cannot hug a linear function that
165	closely, however $A$ is chosen. This is compatible with, and independent of, the
166	bounds above. \Cref{thm:avg} constrains the magnitude of the leading coefficient;
167	Erd\H{o}s--Fuchs constrains the fluctuation around it.
168	
169	\section{Verification}
170	
171	The fibring, the pair bound, the density consequence and the bounded average are
172	formalised in \Lean{} against Mathlib, all depending on \texttt{propext},
173	\texttt{Classical.choice} and \texttt{Quot.sound}.
