\begin{document}
\title{\textbf{The Averaged Representation Count of an Additive Basis}}
\author{C.\ Lando Mills\\
Trabuco Canyon, California\\
\texttt{c.landonmills@gmail.com}\\
ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
\date{11 August 2026}
\maketitle

\begin{abstract}
For $A \subseteq \mathbb{N}$ let $r_A(n)$ count the ordered pairs from $A$
summing to $n$. The partial sum $\sum_{n<N} r_A(n)$ is not an approximation to
anything: it counts exactly the pairs from $A$ whose sum lies below $N$, and both
entries of such a pair are themselves below $N$. Hence the partial sum is at most
$|A \cap [0,N)|^2$.

If $A$ is a basis of order two then the same partial sum is at least $N - N_0$,
because every large $n$ has a representation. The two bounds together give the
square-root density estimate $N - N_0 \le |A \cap [0,N)|^2$, and they squeeze the
average $N^{-1}\sum_{n<N} r_A(n)$ between a quantity tending to $1$ and
$|A \cap [0,N)|^2 / N$. A basis whose counting function is $O(\sqrt N)$
therefore has bounded average, so the average is the wrong statistic for
detecting the irregularity that the Erd\H{o}s--Fuchs theorem concerns.
\end{abstract}

\section{The partial sum is a pair count}

\begin{definition}
For $A \subseteq \mathbb{N}$ put
\[
  r_A(n) \;=\; \#\{ (a,b) \in A \times A \;:\; a + b = n \},
  \qquad
  \operatorname{avg}_A(N) \;=\; \frac1N \sum_{n<N} r_A(n).
\]
\end{definition}

\begin{theorem}[Fibring]
\label{thm:count}
\[
  \boxed{\;
  \sum_{n<N} r_A(n)
   \;=\; \#\{ (a,b) \in A^2 \;:\; a < N,\ b < N,\ a + b < N \}. \;}
\]
\end{theorem}

\begin{proof}
Fibre the right-hand set over the map $(a,b) \mapsto a+b$, which lands in
$\{0, \dots, N-1\}$ by the third condition. The fibre over $n$ consists of the
pairs with $a + b = n$ and both entries in $A$; the side conditions $a, b < N$ are
implied by $a + b = n < N$, so that fibre is counted by $r_A(n)$.
\end{proof}

\begin{corollary}
\label{cor:upper}
$\displaystyle \sum_{n<N} r_A(n) \;\le\; |A \cap [0,N)|^2$.
\end{corollary}

\begin{proof}
Every counted pair has both entries in $A \cap [0,N)$, so the set injects into the
square of that set.
\end{proof}

\section{What a basis forces}

\begin{definition}
$A$ is a \emph{basis of order two} when there is $N_0$ with $n \in A + A$ for
every $n \ge N_0$.
\end{definition}

\begin{theorem}[Square-root density]
\label{thm:sqrt}
If $A$ is a basis of order two with threshold $N_0$, then for every $N \ge N_0$,
\[
  \boxed{\; N - N_0 \;\le\; |A \cap [0,N)|^2 . \;}
\]
\end{theorem}

\begin{proof}
Each $n$ with $N_0 \le n < N$ has a representation, so $r_A(n) \ge 1$; summing
over those $N - N_0$ values gives $N - N_0 \le \sum_{n<N} r_A(n)$, and
\Cref{cor:upper} finishes.
\end{proof}

So a basis of order two has at least $\sqrt{N - N_0}$ elements below $N$:
square-root density is necessary. \Cref{thm:sqrt} is the useful consequence of the
basis hypothesis, and it is a statement about the size of $A$, not about the size
of $r_A$.

\section{The average is bounded}

\begin{theorem}
\label{thm:avg}
If $|A \cap [0,N)| \le C \sqrt{N}$ then $\operatorname{avg}_A(N) \le C^2$.
\end{theorem}

\begin{proof}
By \Cref{cor:upper}, $\sum_{n<N} r_A(n) \le |A \cap [0,N)|^2 \le C^2 N$; divide
by $N$.
\end{proof}

\begin{corollary}
A basis of order two whose counting function is $O(\sqrt N)$ has bounded averaged
representation count. In particular the basis hypothesis alone implies neither
that $\operatorname{avg}_A(N) \to \infty$ nor any growth rate for it.
\end{corollary}

The lower side is equally rigid: by \Cref{thm:sqrt},
$\operatorname{avg}_A(N) \ge 1 - N_0/N$, so for every basis the average is pinned
near $1$ from below. Between the two bounds there is no room for a growth
statement.

\section{Where the Erd\H{o}s--Fuchs theorem lives}

The Erd\H{o}s--Fuchs theorem concerns the error term rather than the average. It
asserts that
\[
  \sum_{n \le N} r_A(n)
   \;=\; cN \;+\; o\!\left( N^{1/4} (\log N)^{-1/2} \right)
\]
is impossible for $c > 0$: the partial sums cannot hug a linear function that
closely, however $A$ is chosen. This is compatible with, and independent of, the
bounds above. \Cref{thm:avg} constrains the magnitude of the leading coefficient;
Erd\H{o}s--Fuchs constrains the fluctuation around it.

\section{Verification}

The fibring, the pair bound, the density consequence and the bounded average are
formalised in \Lean{} against Mathlib, all depending on \texttt{propext},
\texttt{Classical.choice} and \texttt{Quot.sound}.

