\begin{document}
\title{\textbf{The Finite-$m$ Satisfaction Fraction for Optimal Polynomial Intersection: Direct Computation and Observed Convergence}}
\author{C.\ Lando Mills\\
Trabuco Canyon, California\\
\texttt{c.landonmills@gmail.com}\\
ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
\date{1 September 2026}
\maketitle

\begin{abstract}
Jordan et al.\ \cite{Jordan2024} give an exact closed-form-via-eigenvalue expression
(their Lemma 9.2) for the expected number of constraints Decoded Quantum
Interferometry (DQI) satisfies on an instance of Optimal Polynomial Intersection
(OPI, their Definition 2.2), valid at any finite constraint count $m$, and separately
state its $m \to p$ asymptotic limit (their eq.\ 16) as a plain closed form with no
eigenvalue problem to solve. We solve the finite-$m$ eigenvalue problem directly —
shifted power iteration on the stated $(\ell{+}1)\times(\ell{+}1)$ tridiagonal
matrix — at four scales, from a $26\times26$ instance up to a $2478\times2478$
instance, and observe the exact value climbing monotonically toward the fixed
asymptotic limit as $m$ grows. This confirms the limiting relationship the two
expressions assert to each other, watched happening across an $86\times$ range in
matrix dimension, rather than assumed from the two formulas agreeing on paper alone.
\end{abstract}

\section{The Optimal Polynomial Intersection problem}

\begin{definition}[OPI, {\cite[Def.\ 2.2]{Jordan2024}}]
\label{def:opi}
Fix a prime $p$ and an integer $n < p-1$. Let $F_1,\dots,F_{p-1}$ be subsets of
$\mathbb F_p$. An instance of Optimal Polynomial Intersection asks for a polynomial
$Q \in \mathbb F_p[y]$ of degree at most $n-1$ maximizing
\[
  f_{\mathrm{OPI}}(Q) \;=\; \bigl|\{\, y \in \{1,\dots,p-1\} : Q(y) \in F_y \,\}\bigr|.
\]
\end{definition}

An instance is \emph{balanced} when every $|F_i| = r$ for a fixed $r \in \{1,\dots,p-1\}$;
we take $r = \lfloor p/2 \rfloor$ throughout, matching \cite{Jordan2024}'s own worked
examples. \cite[\S5]{Jordan2024} shows OPI is the special case of max-LINSAT over
$\mathbb F_p$ with $m = p-1$ constraints in which the constraint matrix $B$ is
Vandermonde, so $C^\perp = \{d \in \mathbb F_p^m : B^{\mathsf T} d = 0\}$ is a
Reed--Solomon code; syndrome decoding out to $\ell = \lfloor (n+1)/2 \rfloor$ errors
is then the Berlekamp--Massey algorithm, run in polynomial time.

\section{The exact finite-$m$ expression}

\begin{lemma}[{\cite[Lemma 9.2]{Jordan2024}}]
\label{lem:exact}
Let $\langle s^{(m,\ell)} \rangle$ be the expected number of satisfied constraints for
a balanced OPI instance with parameter $r$, measured after DQI's state preparation at
decoding radius $\ell$. If $2\ell+1 < d^\perp$, the minimum distance of $C^\perp$, then
\[
  \boxed{\;
  \langle s^{(m,\ell)} \rangle
  \;=\; \frac{mr}{p} + \frac{\sqrt{r(p-r)}}{p}\, \lambda_{\max}\!\bigl(A^{(m,\ell,d)}\bigr)
  \;}
\]
where $A^{(m,\ell,d)}$ is the real $(\ell{+}1)\times(\ell{+}1)$ symmetric tridiagonal
matrix with diagonal entries $(A)_{kk} = kd$ for $k=0,\dots,\ell$, off-diagonal entries
$(A)_{k,k+1} = (A)_{k+1,k} = a_{k+1} = \sqrt{(k{+}1)(m-k)}$, and
$d = (p-2r)/\sqrt{r(p-r)}$.
\end{lemma}

The expression in \cite{Jordan2024} is stated with $\lambda_{\max}$ appearing after
optimizing over a normalized weight vector $w$; that the optimum equals the largest
eigenvalue of $A$ is the Rayleigh quotient, and \cite[Thm.\ 15.4]{Jordan2024} — the
generalization of \Cref{lem:exact} to $q$-ary Reed--Muller codes — states the same
formula directly in terms of $\lambda_{\max}$, which is the form used throughout this
note.

\begin{proposition}[Prange's asymptotic baseline, {\cite[eq.\ 17]{Jordan2024}}]
\label{prop:prange}
For the same balanced instances, the largest satisfaction fraction achievable
classically in polynomial time that is known to \cite{Jordan2024} is achieved by
Prange's algorithm (their \S11.3): discard all but $n$ of the $m$ constraints,
interpolate the unique degree-${<}n$ polynomial through one point of each, and
measure satisfaction against all $m$; asymptotically,
\[
  \frac{\langle s \rangle_{\mathrm{Prange}}}{m} \;=\; \frac12 + \frac{n}{2p}.
\]
\end{proposition}

\begin{proposition}[DQI's asymptotic limit, {\cite[eq.\ 16]{Jordan2024}}]
\label{prop:asymptotic}
Taking $\ell \to n/2$ and $m \to p$ in \Cref{lem:exact} gives
\[
  \frac{\langle s \rangle_{\mathrm{DQI+BM}}}{p} \;=\; \frac12 + \sqrt{\frac{n}{2p}\Bigl(1-\frac{n}{2p}\Bigr)}.
\]
\end{proposition}

\Cref{prop:prange,prop:asymptotic} are closed forms with no eigenvalue problem to
solve; \Cref{lem:exact} is exact at any finite $m$ but requires solving one.

\section{Direct computation}

\begin{proposition}[Shifted power iteration converges to $\lambda_{\max}$]
\label{prop:power}
Let $A$ be real symmetric and let $c = \max_i \sum_j |A_{ij}|$ (a Gershgorin bound on
the spectral radius). Then $A + cI$ is positive semidefinite, and plain power
iteration on $A + cI$ converges to an eigenvector attaining $\lambda_{\max}(A) + c$,
hence to $\lambda_{\max}(A)$.
\end{proposition}

\begin{proof}
Every eigenvalue $\mu$ of $A$ satisfies $|\mu| \le c$ by Gershgorin's circle theorem,
so every eigenvalue of $A+cI$ lies in $[0,2c]$: $A+cI \succeq 0$, and its largest
eigenvalue is $\lambda_{\max}(A) + c$, strictly the largest in absolute value among a
nonnegative spectrum whenever $\lambda_{\max}(A) > -c$, which holds unless $A=0$.
Power iteration on a symmetric matrix converges to the eigenvector of the
eigenvalue of largest absolute value whenever that eigenvalue has a positive
projection onto the starting vector, which a component-wise positive start
guarantees generically here. Without the shift, power iteration on $A$ directly
would instead converge to whichever of $A$'s two spectral extremes has the larger
magnitude, which need not be $\lambda_{\max}(A)$.
\end{proof}

$A^{(m,\ell,d)}$'s eigenvalue problem was solved this way: 2000 iterations of the
shifted power method on the matrix of \Cref{lem:exact}, at the exact $m$, $\ell$, and
$d$ named by the parameters below, then $\lambda_{\max}(A)$ read off via the Rayleigh
quotient of the converged vector and \Cref{prop:power} applied to recover
$\lambda_{\max}(A)$ from the shifted result.

\section{Results}

Four balanced instances at fixed ratio $n/p \approx 0.495$ (so \Cref{prop:asymptotic}'s
value is fixed near one number across all four, independent of $m$), with $\ell =
\lfloor (n+1)/2 \rfloor$ giving the eigenvalue problem's dimension:

\begin{center}
\begin{tabular}{rrrrr}
\toprule
$p$ & matrix size $(\ell{+}1)$ & $\langle s \rangle / p$ exact (\Cref{lem:exact}) & asymptotic (\Cref{prop:asymptotic}) \\
\midrule
101 & $26 \times 26$ & 0.8938 & 0.9316 \\
1009 & $251 \times 251$ & 0.9229 & 0.9317 \\
2003 & $497 \times 497$ & 0.9259 & 0.9316 \\
10007 & $2478 \times 2478$ & 0.9296 & 0.9316 \\
\bottomrule
\end{tabular}
\end{center}

The exact value increases monotonically across all four scales, closing roughly a
third of the remaining gap to the asymptotic limit with each $\sim 2\times$ increase
in $p$ — the qualitative behavior \Cref{prop:asymptotic} being the $m\to p$ limit of
\Cref{lem:exact} requires, observed rather than assumed.

\section{Verification}

The eigenvalue solve (\Cref{prop:power}'s shifted power iteration on the exact
matrix of \Cref{lem:exact}) and Prange's algorithm (\Cref{prop:prange}, run for real
rather than only evaluated at its closed form) are both implemented directly, in two
byte-identical copies of the same Rust source. Every value in the table above is the
output of a real program run at the stated parameters, not a citation of
\cite{Jordan2024}'s closed forms standing in for a computation.

\begin{thebibliography}{9}
\bibitem{Jordan2024} S.~P.~Jordan, N.~Shutty, M.~Wootters, A.~Zalcman,
A.~Schmidhuber, R.~King, S.~V.~Isakov, T.~Khattar, and R.~Babbush,
\emph{Optimization by Decoded Quantum Interferometry}, arXiv:2408.08292v5
[quant-ph] (2025).

\bibitem{GolubVanLoan} G.~H.~Golub and C.~F.~Van Loan, \emph{Matrix Computations},
4th ed., Johns Hopkins University Press, 2013.
\end{thebibliography}

\end{document}

