< /// decode, not a search over trials.
< pub struct GaoResult {
<     pub p: u64,
<     pub n_points: usize,
<     pub k: usize,
<     pub errors_planted: usize,
<     pub max_correctable: usize,
<     pub decoded_correctly: bool,
