/// The next rung past single-edit search: chains single insertions when
/// the diagnosed defect is a fork/fuse count imbalance too large for
/// `repair()` to close in one edit -- the exact case `diagnose_error`
/// now names a real floor for instead of just failing silently.
///
/// Each step inserts the glyph the count is short of (FFUSE if FSPLIT
/// outnumbers it, FSPLIT otherwise). Every such insertion reduces the
/// count imbalance by exactly one regardless of where it lands -- that
/// part needs no search, the loop bound is the imbalance itself plus a
/// small margin, a real number computed from the word, not a guess at
/// how long is enough. What position-search still buys is pairing:
/// count balance is necessary but not sufficient for the fork/fuse
/// ancestry itself to close, so among positions that reduce the count
/// equally, this prefers whichever also reduces the number of clears
/// exposed with nothing banked behind them (`banked_walk`), a second
/// real instrument reading, not assumed from the count alone. Returns
/// the chain of insertions and the resulting word the moment it verifies,
/// or None if the bound is exhausted without reaching one -- a real
/// negative, not silence, since the bound itself is not a guess.
pub fn repair_chain(&self, word: &str, artifact_type: &str) -> Option<(Vec<RepairType>, String)> {
    if self.verify_repair(word, artifact_type) {
        return Some((Vec::new(), word.to_string()));
    }
    let start_imbalance = fork_fuse_imbalance(word);
    if start_imbalance == 0 {
        return None; // not a count defect this chain addresses
    }
    let max_depth = start_imbalance.unsigned_abs() as usize + 4;
    let mut current = word.to_string();
    let mut chain: Vec<RepairType> = Vec::new();

    for _ in 0..max_depth {
        let need = fork_fuse_imbalance(&current);
        if need == 0 {
            // count is even; whatever remains is a pairing defect, not
            // a count one -- hand off to the ordinary single-edit
            // search for one more real attempt rather than guess blind
            if let Some(best) = self.repair(&current, artifact_type).best_repair {
                if self.verify_repair(&best.repaired_word, artifact_type) {
                    chain.push(best.repair);
                    return Some((chain, best.repaired_word));
                }
            }
            return None;
        }
        let glyph = if need > 0 { '∋' } else { '∈' };
        let mut best_pos = 0usize;
        let mut best_exposed = usize::MAX;
        let mut found = false;
        for pos in 0..=current.chars().count() {
            let candidate = self.insert_at(&current, glyph, pos);
            if self.verify_repair(&candidate, artifact_type) {
                chain.push(RepairType::Insertion(glyph, pos));
                return Some((chain, candidate));
            }
            let exposed = imasm_core::lattice_flow::banked_walk(&candidate)
                .map(|b| b.exposed.len())
                .unwrap_or(usize::MAX);
            if exposed < best_exposed {
                best_exposed = exposed;
                best_pos = pos;
                found = true;
            }
        }
        if !found {
            return None; // no position improves on any measurable axis
        }
        current = self.insert_at(&current, glyph, best_pos);
        chain.push(RepairType::Insertion(glyph, best_pos));
    }
    None
}

