/// search: the exact, not heuristic, fix for a fork/fuse count
/// imbalance. `cyclic_pairs` (imasm_core) is a standard cyclic
/// bracket-matcher, FSPLIT opens, FFUSE closes, tried from every split
/// as a possible start. There is a well-known exact algorithm for
/// closing a one-sided bracket deficit: walk the word, track depth,
/// and the instant a close would take depth negative, insert the
/// missing open immediately before it -- the open and that close pair
/// on the spot, and the walk continues at the depth it already had.
/// `balance_missing_splits`/`balance_missing_fuses` are that walk in
/// each direction. This makes every insertion in one pass, in the
/// exact positions the pairing needs, not a guess ranked by a proxy.
pub fn repair_chain(&self, word: &str, artifact_type: &str) -> Option<(Vec<RepairType>, String)> {
    if self.verify_repair(word, artifact_type) {
        return Some((Vec::new(), word.to_string()));
    }
    let imbalance = fork_fuse_imbalance(word);
    let mut chain: Vec<RepairType> = Vec::new();
    let mut current = word.to_string();

    if imbalance != 0 {
