fn crystal_address_of(word: &str) -> Option<u32> {
    let prog = crate::belnap_ring_shor::program_from_glyphs(word).ok()?;
    let snap = crate::kernel::self_imscribe(&prog);
    let t = crate::imas_ig::IgTuple::from_snapshot(&snap);
    Some(t.crystal_address())
}

/// FSPLIT count minus FFUSE count. Positive: splits outnumber fuses, that
/// many FFUSE insertions close the count gap. Negative: the reverse. Zero
/// count imbalance does not by itself mean the fork/fuse ancestry pairs
/// correctly, only that nothing about the counts rules it out.
fn fork_fuse_imbalance(word: &str) -> isize {
    let splits = word.chars().filter(|&c| c == '∈').count() as isize;
    let fuses = word.chars().filter(|&c| c == '∋').count() as isize;
    splits - fuses
}

/// Exact fix for FFUSE (∋) outnumbering FSPLIT (∈): walk left to right
/// tracking depth (FSPLIT opens, FFUSE closes), and the instant a FFUSE
/// would take depth negative, insert a FSPLIT immediately before it -- the
/// insertion and that FFUSE pair on the spot, depth returns to zero, and
/// the walk continues. Standard minimum-insertion bracket-balancing, one
/// pass, exact positions, not a search. Returns the balanced word and the
/// 0-indexed positions (in the ORIGINAL word's own coordinates) each
/// insertion landed before.
fn balance_missing_splits(word: &str) -> (String, Vec<usize>) {
    let mut out = String::with_capacity(word.len() + 8);
    let mut depth: isize = 0;
    let mut positions = Vec::new();
    for (i, c) in word.chars().enumerate() {
        if c == '∋' {
            if depth == 0 {
                out.push('∈');
                positions.push(i);
            } else {
                depth -= 1;
            }
        } else if c == '∈' {
            depth += 1;
        }
        out.push(c);
    }
    (out, positions)
}

/// Mirror of `balance_missing_splits` for FSPLIT outnumbering FFUSE: walks
/// right to left over the same rule with the roles reversed, inserting a
/// FFUSE immediately after any FSPLIT that has nothing to its right ever
/// closing it.
fn balance_missing_fuses(word: &str) -> (String, Vec<usize>) {
    let chars: Vec<char> = word.chars().collect();
    let mut rev_out: Vec<char> = Vec::with_capacity(chars.len() + 8);
    let mut depth: isize = 0;
    let mut positions = Vec::new();
    for (rev_i, &c) in chars.iter().rev().enumerate() {
        let i = chars.len() - 1 - rev_i;
        if c == '∈' {
            if depth == 0 {
                rev_out.push('∋');
                positions.push(i);
            } else {
                depth -= 1;
            }
        } else if c == '∋' {
            depth += 1;
        }
        rev_out.push(c);
    }
    rev_out.reverse();
    positions.reverse();

